  `CHARACTER_ID` int(11) DEFAULT '0',
  `ACTION` int(11) DEFAULT '0',
  `STAT_TYPE` int(11) DEFAULT '0',
  `GIFT` varchar(45) DEFAULT '0',
  `PARENT` varchar(45) DEFAULT '0',
  `GROUP` int(10) unsigned DEFAULT '0',
  `BACK_UP` VARCHAR(45) DEFAULT '',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


--
